from itertools import combinations
import z3,json,time
from pathlib import Path

def nullvec(rows, width):
    piv={}
    for row in rows:
        x=row
        while x:
            p=x.bit_length()-1
            if p in piv:x^=piv[p]
            else:piv[p]=x;break
    if len(piv)==width:return None
    free=next(p for p in range(width) if p not in piv)
    y=1<<free
    for p in sorted(piv):
        if ((piv[p]&y).bit_count()&1): y^=1<<p
    assert y and all((r&y).bit_count()%2==0 for r in rows)
    return y

for n in (8,9,10):
    ts=list(combinations(range(n),3)); qs=list(combinations(range(n),4))
    H={t:z3.Bool('h'+''.join(map(str,t))) for t in ts}
    F={q:z3.Bool('f'+''.join(map(str,q))) for q in qs}
    S=z3.Solver();S.set(timeout=120000)
    for q in qs:
        ht=[H[t] for t in combinations(q,3)]
        S.add(F[q]==z3.And(ht));S.add(z3.PbLe([(h,1) for h in ht],2) | z3.And(ht))
    for t in ts:S.add(z3.Implies(H[t],z3.Or([F[q] for q in qs if set(t)<=set(q)])))
    for e in combinations(range(n),2):S.add(z3.Or([H[t] for t in ts if set(e)<=set(t)]))
    S.add(z3.PbGe([(h,1) for h in H.values()],(n-2)**2))
    S.add(z3.Sum([z3.If(f,1,0) for f in F.values()])-z3.Sum([z3.If(h,1,0) for h in H.values()])+n*(n-1)//2-n+1>=0)
    S.add(z3.Not(z3.And(list(F.values()))))
    es=list(combinations(range(1,n),2)); pos={e:i for i,e in enumerate(es)}
    vec={t:sum(1<<pos[e] for e in combinations(t,2) if 0 not in e) for t in ts}
    start=time.time()
    for it in range(1000):
        ans=S.check()
        if ans!=z3.sat:
            print(n,it,ans,time.time()-start,flush=True);break
        m=S.model(); ht=[t for t in ts if z3.is_true(m.eval(H[t]))]
        y=nullvec([vec[t] for t in ht],len(es))
        if y is not None:
            S.add(z3.Or([H[t] for t in ts if (vec[t]&y).bit_count()%2]))
            continue
        fq=[q for q in qs if z3.is_true(m.eval(F[q]))]
        print('H1zero',n,it,len(ht),len(fq),time.time()-start,flush=True)
        Path(f'workspace/agent1_closed_candidate_{n}.json').write_text(json.dumps({'n':n,'triangles':ht,'facets':fq}))
        break

